use xiom.io;
type MenuItem = {
  name: Str;
  price: Int;
}

type Cart = {
  items: Vec[MenuItem];
  counts: Vec[Int];
}

fn add_item(cart: &mut Cart, item: MenuItem, qty: Int) {
  cart.items.push(item);
  cart.counts.push(qty);
}

fn calculate_total(cart: &Cart) -> Int {
  var total = 0;
  var i = 0;
  while i < cart.items.len() {
    let item = cart.items.get(i).unwrap();
    let qty = cart.counts.get(i).unwrap();
    total = total + item.price * qty;
    i = i + 1;
  };
  total
}

fn apply_discount(subtotal: Int) -> Int
  requires: subtotal >= 0
{
  if subtotal >= 5000 {
    return subtotal * 10 / 100;
  };
  0
}

fn print_line(item: &MenuItem, qty: Int) {
  io.println(item.name.to_str());
  io.println(qty.to_str());
  io.println(item.price.to_str());
}

fn main() -> Int {
  var cart = Cart{ items: Vec[MenuItem].new(), counts: Vec[Int].new() };

  let salmon = MenuItem{ name: "Grilled Salmon", price: 1895 };
  let steak = MenuItem{ name: "Ribeye Steak", price: 2495 };
  let dessert = MenuItem{ name: "Tiramisu", price: 895 };
  let drink = MenuItem{ name: "Sparkling Water", price: 350 };

  add_item(&mut cart, salmon, 1);
  add_item(&mut cart, steak, 1);
  add_item(&mut cart, dessert, 2);
  add_item(&mut cart, drink, 2);

  let subtotal = calculate_total(&cart);
  let discount = apply_discount(subtotal);
  let tax = (subtotal - discount) * 8 / 100;
  let final_total = subtotal - discount + tax;

  var i = 0;
  while i < cart.items.len() {
    print_line(cart.items.get(i).unwrap(), cart.counts.get(i).unwrap());
    i = i + 1;
  };

  io.println(subtotal.to_str());
  io.println(discount.to_str());
  io.println(tax.to_str());
  io.println(final_total.to_str());

  return 0;
}
